package ru.murad.yourmarket.service.impl;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import ru.murad.yourmarket.dto.response.AdvertisementResponseDto;import ru.murad.yourmarket.exception.TelegramPublicationException;import ru.murad.yourmarket.model.enums.TelegramMessageType;import ru.murad.yourmarket.service.*;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.*;
@Service @RequiredArgsConstructor public class AdvertisementPublicationServiceImpl implements AdvertisementPublicationService {private final PublicationTransactionService transactions;private final TelegramGateway telegram;
@Override public AdvertisementResponseDto publish(UUID id){return run(id,false);}@Override public AdvertisementResponseDto publishFromModeration(UUID id){return run(id,true);}
private AdvertisementResponseDto run(UUID id,boolean moderation){var claim=transactions.claim(id,moderation);if(!claim.shouldPublish())return claim.existing();try{transactions.markTelegramCallStarted(id,claim.operationId());List<Integer> primary=telegram.publishAdvertisementPrimaryMessages(claim.advertisement());boolean contact=telegram.needsSeparateContactMessage(claim.advertisement());transactions.saveProgress(id,claim.operationId(),primary,primary.size()>1?TelegramMessageType.MEDIA_GROUP_ITEM:TelegramMessageType.PHOTO,!contact);if(contact){transactions.markTelegramCallStarted(id,claim.operationId());Integer contactId=telegram.publishAdvertisementContactMessage(claim.advertisement());transactions.saveProgress(id,claim.operationId(),List.of(contactId),TelegramMessageType.CONTACT,true);}}catch(RuntimeException ex){try{transactions.reconciliationRequired(id,claim.operationId(),ex.getMessage());}catch(RuntimeException mark){ex.addSuppressed(mark);}throw new TelegramPublicationException("Публикация требует сверки",ex);}try{return transactions.complete(id,claim.operationId());}catch(RuntimeException ex){try{transactions.reconciliationRequired(id,claim.operationId(),ex.getMessage());}catch(RuntimeException mark){ex.addSuppressed(mark);}throw new TelegramPublicationException("Публикация требует сверки",ex);}}
}
